Export.Routine:
#include Ensemble
set pName="ITF Source Control"
set pLink = "/csp/healthshare/itfcommon/IHC.ITF.SrcCtrlPkg.Login.cls"
set stat = ##class(%CSP.Portal.Utils).%AddFavorite(pName,pLink) Write !, stat Quit
Kill pFavorites Set tSC = ##class(%SYS.Portal.Users).%GetFavoritesForUser(.tFavorites) If $$$ISERR(tSC) Quit Write !, tSC Set n = 0 Set tName = $O(tFavorites("")) While (tName'="") { Set tLink = $G(tFavorites(tName)) Set tLink = ##class(%CSP.Page).Link(tLink) Write !, tName,"",tLink
} quit set st = ##class(%CSP.Portal.Utils).%GetFavoritesForUser(.pn) Write !, st Write !, $DATA(pn) , ! quit
